import {
  Dialog,
  DialogContent,
  DialogHero,
  DialogBody,
  DialogFooter,
  DialogSecondaryAction,
  DialogDestructiveAction,
} from "@/components/ui/dialog";
import { Textarea } from "@/components/ui/textarea";
import type { Job } from "./types";

interface RemoveJobDialogProps {
  open: boolean;
  detailJob: Job | null;
  deleteReason: string;
  deleting: boolean;
  onOpenChange: (open: boolean) => void;
  onReasonChange: (value: string) => void;
  onCancel: () => void;
  onConfirm: () => void;
}

export const RemoveJobDialog = ({
  open,
  detailJob,
  deleteReason,
  deleting,
  onOpenChange,
  onReasonChange,
  onCancel,
  onConfirm,
}: RemoveJobDialogProps) => {
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent>
        <DialogHero
          title="Remove Job"
        />
        <div className="space-y-3">
          <DialogBody>
            <p>
              This will cancel the job and notify the poster{detailJob?.helper_id ? " and assigned Helpr" : ""}. Please provide a reason:
            </p>
          </DialogBody>
          <Textarea
            aria-label="Reason for cancelling job"
            placeholder="e.g. This listing violates our community guidelines…"
            value={deleteReason}
            onChange={(e) => onReasonChange(e.target.value)}
            rows={3}
          />
          {detailJob && (
            <div className="rounded-ds-sm bg-secondary/30 p-3">
              <p className="text-ds-11 text-muted-foreground">Job being removed</p>
              <p className="text-ds-13 font-medium text-foreground">{detailJob.title}</p>
              <p className="text-ds-11 text-muted-foreground">${detailJob.budget} · {detailJob.location}</p>
            </div>
          )}
        </div>
        {/* `ghost` — a secondary sitting beside a primary is bare text in every
            other dialog footer in the app; `outline` is reserved for a footer
            whose only control is the dismiss. `gap-2` restated DialogFooter's
            own gap. */}
        <DialogFooter>
          <DialogSecondaryAction onClick={onCancel}>
            Cancel
          </DialogSecondaryAction>
          <DialogDestructiveAction
            onClick={onConfirm}
            disabled={!deleteReason.trim() || deleting}
          >
            {deleting ? "Removing…" : "Remove & Notify"}
          </DialogDestructiveAction>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
};
